/**
 * The Quran text, metadata and the 604-page layout, as generated by scripts/build-quran-data.mjs.
 *
 * The text is Tanzil's Uthmani text, verbatim. Words are only ever *displayed* from these strings: a "token" is
 * one word of an ayah exactly as Tanzil writes it, with the pause / sajdah / rub-el-hizb signs that belong to it.
 * Token word numbers are 1-based and match Tilawa's `{ surah, ayah, word }` references (checked at build time).
 */
import textData from "./generated/quran-text.json";
import metaData from "./generated/meta.json";
import layoutData from "./generated/layout.json";

export type LineSpec =
  | readonly [0, number] // surah header
  | readonly [1, number] // basmala
  | readonly [2, number, number, number, number]; // words: first token, last token, width (em*1000), ayah ends

export interface Token {
  s: number;
  a: number;
  w: number;
  text: string;
  /** Last word of its ayah: an ayah marker follows it. */
  end: boolean;
}

export interface Surah {
  ayas: number;
  name: string;
  tname: string;
  ename: string;
  type: string;
}

export const TANZIL_NOTICE: string = textData.notice;
export const SURAHS: Surah[] = metaData.suras;
export const PAGE_COUNT = 604;
export const PAGES = layoutData.pages as unknown as LineSpec[][];

/** The only non-word tokens in Tanzil's text: pause marks, rub el hizb (۞) and sajdah (۩). */
const SIGNS = ["ۖ", "ۗ", "ۘ", "ۙ", "ۚ", "ۛ", "ۜ", "۞", "۩"];
const BASMALA_SURAHS = new Map<number, string>();
export const TOKENS: Token[] = [];
/** ayahFirst[s][a] = index of the ayah's first token. */
const ayahFirst: number[][] = [[]];

{
  let i = 0;
  for (let s = 1; s <= 114; s++) {
    const row: number[] = [0];
    for (let a = 1; a <= SURAHS[s - 1].ayas; a++, i++) {
      let parts = textData.ayahs[i].split(" ");
      if (a === 1 && s !== 1 && s !== 9) {
        BASMALA_SURAHS.set(s, parts.slice(0, 4).join(" "));
        parts = parts.slice(4);
      }
      row.push(TOKENS.length);
      let w = 0;
      let prefix = "";
      for (const p of parts) {
        if (!SIGNS.includes(p)) {
          TOKENS.push({ s, a, w: ++w, text: prefix + p, end: false });
          prefix = "";
        } else if (p === "۞") prefix = p + " ";
        else TOKENS[TOKENS.length - 1].text += " " + p;
      }
      TOKENS[TOKENS.length - 1].end = true;
    }
    ayahFirst.push(row);
  }
}

/** The basmala as Tanzil prints it at the head of the surah (absent for surahs 1 and 9). */
export const basmalaOf = (s: number) => BASMALA_SURAHS.get(s) ?? BASMALA_SURAHS.get(2)!;

export function tokenIndex(s: number, a: number, w: number): number {
  const first = ayahFirst[s]?.[a];
  if (first === undefined) return -1;
  return first + Math.max(0, w - 1);
}

export function ayahTokenRange(s: number, a: number): [number, number] {
  const first = ayahFirst[s][a];
  const next = a < SURAHS[s - 1].ayas ? ayahFirst[s][a + 1] : s < 114 ? ayahFirst[s + 1][1] : TOKENS.length;
  return [first, next - 1];
}

// token -> page (1-based)
const pageOfToken = new Uint16Array(TOKENS.length);
const pageFirstToken: number[] = [];
PAGES.forEach((lines, p) => {
  for (const l of lines) {
    if (l[0] !== 2) continue;
    if (pageFirstToken[p] === undefined) pageFirstToken[p] = l[1];
    for (let t = l[1]; t <= l[2]; t++) pageOfToken[t] = p + 1;
  }
});
export const pageOf = (token: number) => pageOfToken[token] || 1;
export const pageOfAyah = (s: number, a: number) => pageOf(tokenIndex(s, a, 1));

/** Surah of the first word on the page, and every surah that begins on it. */
export function surahsOnPage(page: number): number[] {
  const first = TOKENS[pageFirstToken[page - 1]].s;
  const set = new Set([first]);
  for (const l of PAGES[page - 1]) if (l[0] === 0) set.add(l[1]);
  return [...set];
}

const juzStarts = metaData.juzStarts as [number, number][];
export function juzOfPage(page: number): number {
  const t = TOKENS[pageFirstToken[page - 1]];
  let j = 1;
  for (let i = 0; i < juzStarts.length; i++) {
    const [s, a] = juzStarts[i];
    if (t.s > s || (t.s === s && t.a >= a)) j = i + 1;
  }
  return j;
}

export const toArabicDigits = (n: number) => String(n).replace(/\d/g, (d) => "٠١٢٣٤٥٦٧٨٩"[+d]);
